/* V3.1 views: cockpit, signal→judgement→action, flows, heatmap, timeline, project links, longlist, actionable pool.
   Loaded before app.js; uses the shared helpers declared there at call time. */
'use strict';
let longState={preset:'chief-combat',title:'主策（需战斗背景）',domains:['战斗体系'],minScope:2,chief:true,genre:''},flowFocusProject='';
const prTag=p=>tag(p,p==='P0'?'red':p==='P1'?'amber':'');
const personBtn=(id,extra='')=>action('person',esc(person(id)?.name||id)+extra,`data-id="${id}"`,'link','person');
function poolButton(id){return action('pool',db.pool.includes(id)?'已在人才池 ✓':'＋ 加入人才池',`data-id="${id}"`,'btn secondary','pool');}

/* ---------------- 情报驾驶舱 ---------------- */
function cockpit(){
 const d=M.dashboard(db),metrics=M.activityMetrics(db),top=d.analyses[0],h=M.health(db),f=M.flows(db);
 const stats=[['people','已发布去重人员',d.people,`${d.companies} 家公司 · ${d.projects} 个项目 · 非市场总量`],['delta','本轮新增 / 补证任职',`${d.added}/${d.supplemented}`,'相对历史底库；由人审发布产生'],['p0','P0 研判信号',d.p0.length,`共 ${d.analyses.length} 条研判 · 逾期复核 ${d.overdue.length}`],['review',role==='hr'?'待审核 / 待核验':'待核验关系',role==='hr'?pending():db.relationships.filter(r=>r.processStatus==='待核验').length,'未知不代表否定'],['poolDue','人才池待复核',`${d.poolDue}/${d.pool}`,'已过下次复核日 / 池内总数']];
 return `<div class="guide row spread"><div><b>新手演示 3 分钟</b><span class="muted">　先看窗口信号，再录入林序访谈，观察查询、流向与长名单的联动。</span></div><div class="row">${role==='hr'?action('nav','① 录入与人审','data-page="intake"','link','extract'):''}${action('demoQuery','② 组合查询','','link','query')}${action('nav','③ 需求长名单','data-page="longlist"','link','longlist')}${action('project','④ 历史组织','data-id="G-A1" data-period="2022"','link','projects')}</div></div>
 <div class="stats stats5">${stats.map(([k,t,n,s])=>`<div class="stat-wrap">${act('stat',`<span class="stat-top">${t}<span>↗</span></span><strong>${typeof n==='number'?String(n).padStart(2,'0'):n}</strong><small>${s}</small>`,`data-key="${k}"`,'stat')}${info(k==='review'&&role==='biz'?'relation':({people:'people',delta:'delta',p0:'analysis',review:'review',poolDue:'poolFollow'})[k])}</div>`).join('')}</div>
 ${top?headline(top):''}
 <div class="grid">
  <section class="panel"><div class="panel-head"><h2>信号 → 判断 → 建议行动</h2><div class="row">${tag('判断与事实分层','amber')}${info('analysis')}</div></div><p class="muted">事实层只引用已发布事件与原文；判断层是 HRBP 的工作判断，单独存储、可编辑、不进入查询。近30天新发生事件 ${metrics.newEvents.length} 条 · 历史补录 ${metrics.historical.length} 条 · ${action('stat','近30天新采集资料 '+metrics.collected.length+' 份','data-key="news"','link','news')}</p>${d.analyses.map(a=>analysisCard(a)).join('')}${db.events.filter(e=>e.processStatus==='已发布'&&M.supported(db,e)&&!(db.analyses||[]).some(a=>a.eventId===e.id)).map(e=>`<div class="task"><div><span class="muted">发生 ${e.date} · 采集 ${e.collected} · 尚无研判</span><h3>${esc(e.title)}</h3><p class="muted">${esc(e.fact)}</p></div><div class="row">${action('event','事实与变化',`data-id="${e.id}"`,'link','compare')}${role==='hr'?action('analysis','写研判',`data-id="${e.id}"`,'link','analysis'):''}</div></div>`).join('')}</section>
  <div class="stack">
   <section class="panel"><div class="panel-head"><h2>数据健康度</h2>${info('health')}</div><p class="muted">不合成单一分数：每项都由字段证据直接计数，点击查看具体记录。</p>${h.map(x=>{const warn=x.good==='high'?x.pct<70:x.pct>40;return act('health',`<span>${esc(x.label)}</span><span class="bartrack"><span class="barfill ${warn?'warn':''}" style="display:block;width:${x.pct}%"></span></span><span>${x.value}/${x.total}</span>`,`data-key="${x.key}"`,'barrow health-row')}).join('')}</section>
   <section class="panel"><div class="panel-head"><h2>人才流动摘要</h2>${action('nav','流向与能力 →','data-page="flow"','link','flow')}</div>${f.edges.slice(0,5).map(e=>`<div class="task">${act('flowEdge',`${esc(project(e.from).name)} → ${esc(project(e.to).name)}`,`data-id="${e.from}>${e.to}"`,'link')}<span class="row">${e.inferred?tag('含推定边界','amber'):''}${tag(e.count+' 人')}</span></div>`).join('')||'<p class="muted">尚无跨项目任职路径。</p>'}<p class="muted">去向未收录 ${f.exits.length} 人：最近任职已结束但库内没有后续记录，不等于离职或求职。</p></section>
  </div>
  <section class="panel"><div class="panel-head"><h2>核心策划能力分布</h2>${action('nav','热力图 →','data-page="flow"','link','heatmap')}</div><div class="bars">${M.DOMAINS.map(c=>{const n=M.query(db,{capability:c}).length;return act('cap',`<span>${c}</span><span class="bartrack"><span class="barfill" style="display:block;width:${n/Math.max(1,d.people)*100}%"></span></span><span>${n} 人</span>`,`data-cap="${c}"`,'barrow')}).join('')}</div><p class="muted section-space">按人员 ID 去重，多能力分组不可相加。能力证据来自职责，不从项目或 Title 推断。</p>${info('query')}</section>
  <section class="panel"><div class="panel-head"><h2>快速人才查询</h2>${info('query')}</div><p class="muted">战斗职责与主策任职，可以由同一人的不同经历证明。</p><form id="quickSearch" class="searchbox"><input name="query" aria-label="快速人才查询" value="有 MMO 战斗经验且做过主策的人"><button class="btn">查询 →</button></form><div class="path"><div class="pathnode"><strong>MMO 战斗职责</strong><small>每项对应任职与原文</small></div><span class="arrow">∩</span><div class="pathnode"><strong>曾任主策</strong><small>审核前只有顾航命中</small></div></div><p class="muted">林序现有主策经历不会因为访谈重复提及而新增一条。</p></section>
  <section class="panel span2"><div class="panel-head"><h2>重点项目与组织观察</h2>${action('nav','全部项目 →','data-page="projects"','link','projects')}</div><div class="project-grid">${projectCards(db.projects)}</div></section>
  <section class="panel span2"><div class="panel-head"><h2>${role==='hr'?'情报更新与待办':'组织信息缺口'}</h2>${role==='hr'?action('nav','审核工作台 →','data-page="review"','link','review'):info('relation')}</div>${role==='hr'?tasksHtml():db.relationships.filter(r=>r.processStatus==='待核验').map(r=>`<div class="task"><span>${person(r.subjectId).name}与${person(r.objectId).name}：${esc(r.gap)}</span>${action('relation','查看线索',`data-id="${r.id}"`)}</div>`).join('')}</section>
 </div>`;
}
function headline(a){const e=a.event;return `<section class="headline"><div class="headline-main"><div class="row">${prTag(a.priority)}<span class="eyebrow light">人才窗口信号 · ${esc(a.kind)}</span>${a.overdue?tag('已过复核日','red'):''}</div><h2>${esc(e.title)}</h2><p>${esc(a.signal)}</p><p class="headline-action"><b>建议行动</b> ${esc(a.action)}</p><small>${esc(a.window)} · 复核日 ${esc(a.reviewBy||'未设')}　|　事实依据：${esc(e.fact)}</small></div><div class="headline-side">${action('event','事实与变化',`data-id="${e.id}"`,'btn','compare')}${act('nav','去向与流动 →','data-page="flow"','btn ghost')}${projectLink(e.projectId,e.before)}</div></section>`;}
function analysisCard(a){const e=a.event;return `<article class="insight-card p-${a.priority.toLowerCase()}"><div class="row spread"><div class="row">${prTag(a.priority)}<b>${esc(e.title)}</b></div><span class="row">${tag('发生 '+e.date)}${a.overdue?tag('已过复核日 '+a.reviewBy,'red'):tag('复核 '+(a.reviewBy||'未设'))}</span></div><div class="layer fact"><span class="layer-label">① 事实 · 已发布</span><p>${esc(e.fact)}</p><p class="muted">缺口：${esc(e.gap)}</p>${evidenceLink(e.evidenceIds)}</div><div class="layer judge"><span class="layer-label">② 信号与判断 · ${esc(a.kind)}（不进入查询）</span><p><b>信号</b>　${esc(a.signal)}</p><p><b>判断</b>　${esc(a.judgement)}</p></div><div class="layer act"><span class="layer-label">③ 建议行动</span><p>${esc(a.action)}</p><p class="muted">窗口期：${esc(a.window)} · ${esc(a.author)} · 更新 ${esc(String(a.updated).slice(0,10))}</p></div><div class="actions">${action('event','查看事实与变化',`data-id="${e.id}"`,'link','compare')}${projectLink(e.projectId,e.after)}${role==='hr'?action('analysis','编辑研判',`data-id="${e.id}"`,'link','analysis'):''}</div></article>`;}

/* ---------------- 人才流动与能力 ---------------- */
function flowNet(f){
 const W=820,H=420,CX=W/2,CY=H/2-6,ps=[...db.projects].sort((a,b)=>a.companyId.localeCompare(b.companyId)||a.start-b.start),pos={},rad={};
 ps.forEach((p,i)=>{const t=-Math.PI/2+i*2*Math.PI/ps.length;pos[p.id]={x:CX+300*Math.cos(t),y:CY+140*Math.sin(t)};rad[p.id]=20+M.projectPeople(db,p.id).length*2;});
 const unit=(x,y)=>{const l=Math.hypot(x,y)||1;return [x/l,y/l];};
 const draw=(e,kind)=>{const a=pos[e.from],b=pos[e.to],mx=(a.x+b.x)/2,my=(a.y+b.y)/2,cx=mx+(CX-mx)*.45,cy=my+(CY-my)*.45,[ux,uy]=unit(cx-a.x,cy-a.y),[vx,vy]=unit(b.x-cx,b.y-cy),sx=a.x+ux*(rad[e.from]+2),sy=a.y+uy*(rad[e.from]+2),ex=b.x-vx*(rad[e.to]+6),ey=b.y-vy*(rad[e.to]+6),w=2+e.count*2.5,key=kind+'|'+e.from+'>'+e.to;return `<g class="flow-edge ${kind==='candidate'?'inferred':''} ${flowFocusProject&&![e.from,e.to].includes(flowFocusProject)?'dim':''}" data-action="flowEdge" data-id="${key}" tabindex="0" role="button" aria-label="${esc(project(e.from).name)}到${esc(project(e.to).name)} ${e.count}人 · ${kind==='confirmed'?'明确转岗':'履历先后'}"><path d="M${sx.toFixed(1)},${sy.toFixed(1)} Q${cx.toFixed(1)},${cy.toFixed(1)} ${ex.toFixed(1)},${ey.toFixed(1)}" stroke-width="${w}" marker-end="url(#arrow${kind==='candidate'?'I':''})"/><text x="${((sx+2*cx+ex)/4).toFixed(1)}" y="${((sy+2*cy+ey)/4).toFixed(1)}">${e.count}</text></g>`;};
 const edges=[...f.edges.map(e=>draw(e,'confirmed')),...f.candidateEdges.map(e=>draw(e,'candidate'))].join('');
 const nodes=ps.map(p=>{const n=f.net[p.id],r=rad[p.id],o=pos[p.id],below=o.y>=CY,focus=flowFocusProject===p.id;return `<g class="flow-node ${focus?'active':''}" data-action="flowProject" data-id="${p.id}" tabindex="0" role="button" aria-label="筛选${esc(p.name)}流动"><circle cx="${o.x}" cy="${o.y}" r="${r}"/><text x="${o.x}" y="${o.y+5}" class="n1">${esc(p.name)}</text><text x="${o.x}" y="${below?o.y+r+16:o.y-r-22}" class="n3">${esc(db.companies.find(c=>c.id===p.companyId).name)}</text><text x="${o.x}" y="${below?o.y+r+31:o.y-r-8}" class="n2">确认入 ${n.in} · 出 ${n.out} · 待核验 ${n.candidateIn+n.candidateOut}</text></g>`;}).join('');
 return `<div class="flow-wrap"><svg viewBox="0 0 ${W} ${H}" class="flow-svg" role="img" aria-label="项目间人才流向与待核验路径"><defs><marker id="arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0,0L10,5L0,10z" fill="#2c8a79"/></marker><marker id="arrowI" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="4" markerHeight="4" orient="auto-start-reverse"><path d="M0,0L10,5L0,10z" fill="#c09331"/></marker></defs>${edges}${nodes}</svg></div>`;
}
function moveTable(rows,kind){return `<div class="tablewrap"><table><thead><tr><th>路径</th><th>人数</th><th>人员（年份）</th><th>依据</th></tr></thead><tbody>${rows.map(e=>`<tr><td>${projectLink(e.from)} → ${projectLink(e.to)}</td><td>${e.count}</td><td>${e.moves.map(m=>`${personBtn(m.personId)} <small class="muted">${m.year}${m.inferred?' · 边界待核验':''}${m.gap?' · 有空档':''}</small>`).join('<br>')}</td><td>${act('flowEdge',kind==='confirmed'?'明确事件与原文':'先后经历与原文',`data-id="${kind}|${e.from}>${e.to}"`)}</td></tr>`).join('')||'<tr><td colspan="4">暂无。</td></tr>'}</tbody></table></div>`;}
function flowView(){
 const f=M.flows(db),hm=M.heatmap(db),max=Math.max(1,...hm.rows.flatMap(r=>r.cells.map(c=>c.count))),rel=e=>!flowFocusProject||e.from===flowFocusProject||e.to===flowFocusProject,confirmed=f.edges.filter(rel),candidates=f.candidateEdges.filter(rel),concurrent=f.concurrent.filter(x=>!flowFocusProject||x.projectIds.includes(flowFocusProject)),exits=f.exits.filter(x=>!flowFocusProject||x.projectId===flowFocusProject),focus=flowFocusProject&&project(flowFocusProject);
 return `<section class="panel"><div class="panel-head"><div><h2>项目间人才流向网络</h2><p class="muted">${esc(f.method)}</p></div>${info('flow')}</div><div class="actions flow-filter">${act('flowProject','全部项目','data-id=""',flowFocusProject?'btn secondary':'btn')}${db.projects.map(p=>act('flowProject',esc(p.name),`data-id="${p.id}"`,flowFocusProject===p.id?'btn':'btn secondary')).join('')}</div>${focus?`<p class="hint">当前筛选：${esc(focus.name)}。图中弱化无关路径；下方明细仅保留相关记录。</p>`:''}<div class="legend"><span class="solid-sample"></span> 绿色实线：有已发布事件明确关联前后任职 <span class="dashed-sample"></span> 黄色虚线：仅履历先后，待核验 · 线宽 = 去重人数 · 点击节点筛选</div>${flowNet(f)}</section>
 <section class="panel section-space"><div class="panel-head"><h2>明确转岗 · ${confirmed.reduce((n,e)=>n+e.count,0)} 人次</h2>${info('flowConfirmed')}</div>${moveTable(confirmed,'confirmed')}<p class="muted">只有本表参与下方“确认流入 / 流出”。同一人有多次明确转岗时按事件分别计数。</p></section>
 <section class="panel section-space"><div class="panel-head"><h2>履历先后 · 待核验 ${candidates.reduce((n,e)=>n+e.count,0)} 人次</h2>${info('flowCandidate')}</div>${moveTable(candidates,'candidate')}<p class="muted">这里只确认任职先后，未见明确转岗事件；不进入净流量。可沿人物、任职和来源继续补证。</p></section>
 <section class="panel section-space"><div class="panel-head"><h2>同期跨项目 · ${concurrent.length} 条</h2>${info('flowConcurrent')}</div>${concurrent.map(x=>`<div class="task"><div>${personBtn(x.personId)} · ${x.projectIds.map(id=>projectLink(id)).join(' ＋ ')}<p class="muted">${x.start}–${x.end} 年 · ${esc(x.warning)}</p></div>${act('flowConcurrent','查看两段任职',`data-id="${x.id}"`,'link')}</div>`).join('')||'<p class="muted">当前筛选下无同期跨项目任职。</p>'}</section>
 <div class="grid section-space"><section class="panel"><div class="panel-head"><h2>项目确认净流动</h2>${info('flowNet')}</div><div class="tablewrap"><table><thead><tr><th>项目</th><th>确认流入</th><th>确认流出</th><th>待核验路径</th><th>同期任职</th></tr></thead><tbody>${db.projects.filter(p=>!flowFocusProject||p.id===flowFocusProject).map(p=>{const n=f.net[p.id];return `<tr><td>${projectLink(p.id)}</td><td>${n.in}</td><td>${n.out}</td><td>${n.candidateIn+n.candidateOut}</td><td>${n.concurrent}</td></tr>`;}).join('')}</tbody></table></div><p class="muted">确认净值 = 明确转岗流入 − 明确转岗流出。去向未收录单列，不混入净值。</p></section>
 <section class="panel"><div class="panel-head"><h2>去向未收录 · ${exits.length} 人</h2>${info('exits')}</div>${exits.sort((a,b)=>b.year-a.year).map(x=>`<div class="task"><div>${personBtn(x.personId)}<p class="muted">最近已知：${esc(project(x.projectId).name)} · ${esc(M.roleAt(db.jobs.find(j=>j.id===x.jobId),'all',db))} · 止于 ${x.year} 年</p></div><div class="row">${evidenceLink(x.evidenceIds)}${poolButton(x.personId)}</div></div>`).join('')||'<p class="muted">暂无。</p>'}<p class="muted">对应 destination pending：库内没有后续记录，不等于离职、待业或求职。</p></section></div>
 <section class="panel section-space"><div class="panel-head"><h2>能力热力图 · 项目 × 能力域</h2>${info('heatmap')}</div><p class="muted">格内数字 = 该项目有此能力职责证据的去重人数；括号 = 其中责任范围达到“带领小组 / 模块”及以上的人数。点击格子进入组合查询。</p><div class="tablewrap"><table class="heat"><thead><tr><th>项目</th>${hm.domains.map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${hm.rows.map(r=>`<tr><td>${projectLink(r.project.id)}<br><small class="muted">${esc(r.project.genre)}</small></td>${r.cells.map(c=>`<td>${c.count?act('heat',`<b>${c.count}</b><small>（${c.leads}）</small>`,`data-project="${r.project.id}" data-cap="${c.domain}" style="background:rgba(34,155,137,${(0.12+0.6*c.count/max).toFixed(2)})"`,'heat-cell'):'<span class="heat-empty">—</span>'}</td>`).join('')}</tr>`).join('')}</tbody><tfoot><tr><th>样本合计</th>${hm.totals.map(t=>`<th>${t.people} 人 · 带组以上 ${t.leads}<br><small>${t.projects} 个项目${t.leads<=2?' · 样本内带组人数少':''}</small></th>`).join('')}</tr></tfoot></table></div><p class="muted">“—”仅表示样本库没有收录该能力的职责证据，不代表项目没有此类人才；不计算主观稀缺度。</p></section>`;
}

/* ---------------- 架构演变 & 项目关系 ---------------- */
function timelineView(p){
 const t=M.timeline(db,p.id),max=Math.max(1,...t.map(x=>x.count));
 return `<section class="panel section-space"><div class="panel-head"><h2>架构演变时间轴 · ${p.start}–${db.observationDate.slice(0,4)}</h2>${info('timeline')}</div><p class="muted">每年：阶段、已收录人数、流入 / 流出与事件，均由已发布任职回算。点击年份查看当年组织。推定边界年份的人数可能包含时间待核验人员。</p><div class="tl">${t.map(y=>`<div class="tl-year ${String(y.year)===projectState.period?'current':''}">${act('tlYear',`<b>${y.year}</b><small>${esc(y.stage)}</small>`,`data-year="${y.year}"`,'tl-head')}<div class="tl-bar" title="${y.count} 人"><span style="height:${Math.max(4,y.count/max*100)}%"></span></div><small class="tl-count">${y.count} 人</small>${y.inflow.map(m=>act('person',`↘ ${esc(person(m.personId).name)}<small>明确转岗来自 ${esc(project(m.from).name)}</small>`,`data-id="${m.personId}"`,'tl-chip in')).join('')}${y.outflow.map(m=>act('person',`↗ ${esc(person(m.personId).name)}<small>明确转岗至 ${esc(project(m.to).name)}${m.inferred?' · 边界待核验':''}</small>`,`data-id="${m.personId}"`,'tl-chip out')).join('')}${y.candidateIn.map(m=>act('person',`? ${esc(person(m.personId).name)}<small>履历先后：来自 ${esc(project(m.from).name)}</small>`,`data-id="${m.personId}"`,'tl-chip candidate')).join('')}${y.candidateOut.map(m=>act('person',`? ${esc(person(m.personId).name)}<small>履历先后：去 ${esc(project(m.to).name)}</small>`,`data-id="${m.personId}"`,'tl-chip candidate')).join('')}${y.concurrent.map(x=>act('flowConcurrent',`∥ ${esc(person(x.personId).name)}<small>同期跨项目，待核验</small>`,`data-id="${x.id}"`,'tl-chip concurrent')).join('')}${y.exits.map(x=>act('person',`… ${esc(person(x.personId).name)}<small>此后去向未收录</small>`,`data-id="${x.personId}"`,'tl-chip exit')).join('')}${y.events.map(e=>act('event','◆ '+esc(e.title),`data-id="${e.id}"`,'tl-chip ev')).join('')}</div>`).join('')}</div><div class="legend section-space"><span class="tl-key in"></span>明确流入 <span class="tl-key out"></span>明确流出 <span class="tl-key candidate"></span>履历先后待核验 <span class="tl-key concurrent"></span>同期跨项目 <span class="tl-key exit"></span>任职结束且去向未收录 <span class="tl-key ev"></span>已发布事件</div></section>${projectLinksPanel(p.id)}`;
}
function projectLinksPanel(pid){const ls=M.linksFor(db,pid);return `<section class="panel section-space"><div class="panel-head"><h2>项目关系图谱</h2>${info('projectLinks')}</div><div class="legend"><span class="solid-sample"></span> 实线：有原文明确支持的项目关系 <span class="dashed-sample"></span> 虚线：待核验线索（不进入正式事实）</div>${ls.map(l=>`<div class="relation-edge ${l.processStatus==='待核验'?'pending':''}"><div class="relation-node">${projectLink(l.fromId)}<small>${esc(db.companies.find(c=>c.id===project(l.fromId).companyId).name)}</small></div>${act('plink',`${l.processStatus==='待核验'?'? 待核验：':''}${esc(l.type)} →`,`data-id="${l.id}"`,'relation-line')}<div class="relation-node">${projectLink(l.toId)}<small>${l.year} 年 · ${esc(l.processStatus)}</small></div></div>`).join('')||'<p class="muted">该项目暂无收录的项目间关系。</p>'}<p class="muted">成员迁移不等于续作或项目血缘；“疑似同一团队 / 玩法延续”只作为线索单独核验。</p></section>`;}

/* ---------------- 需求 → 分层长名单 ---------------- */
function legacyLonglistView(){
 let rows=[],err='';try{rows=M.longlist(db,longState);}catch(e){err=e.message;}
 const A=rows.filter(r=>r.tier==='A'),Bt=rows.filter(r=>r.tier==='B');
 return `<section class="panel"><div class="panel-head"><h2>招聘需求 → 可解释的分层长名单</h2>${info('longlist')}</div><p class="muted">规则版、可复现：只用已发布任职、能力职责与字段证据匹配，不调用 AI、不评估人才质量或求职意向。A 层 = 全部硬条件满足；B 层 = 至少一项能力有证据但有缺口。</p><div class="tabs">${M.LONGLIST_PRESETS.map(p=>act('llPreset',p.title,`data-id="${p.id}"`,longState.preset===p.id?'active':'')).join('')}</div><form id="longlistForm" class="ll-form"><label class="field">需求名称<input name="title" value="${esc(longState.title)}" maxlength="40"></label><fieldset class="field"><legend>必需能力域（职责证据）</legend><div class="checks">${M.DOMAINS.map(d=>`<label><input type="checkbox" name="domains" value="${d}" ${longState.domains.includes(d)?'checked':''}>${d}</label>`).join('')}</div></fieldset><label class="field">最低责任范围<select name="minScope">${[1,2,3,4].map(n=>`<option value="${n}" ${+longState.minScope===n?'selected':''}>${M.SCOPE_LABEL[n]}</option>`).join('')}</select></label><label class="field">项目类型偏好（不作淘汰）<select name="genre"><option value="">不限</option>${['动作','开放世界','回合制','科幻','东方玄幻'].map(g=>`<option ${longState.genre===g?'selected':''}>${g}</option>`).join('')}</select></label><label class="checks"><span><input type="checkbox" name="chief" ${longState.chief?'checked':''}>需做过主策（可由另一段经历证明）</span></label><div class="actions"><button class="btn">生成长名单 →</button>${rows.length?act('llExport','导出 CSV','','btn secondary'):''}</div></form>${err?`<p class="error" role="alert">${esc(err)}</p>`:''}</section>
 ${err?'':`<section class="panel section-space"><div class="panel-head"><h2>A 层 · 硬条件全部有证据 · ${A.length} 人</h2>${tag('优先研究','green')}</div>${A.map(llCard).join('')||'<p class="empty">暂无全部满足的人员。可放宽责任范围，或审核新情报后再看。</p>'}</section><section class="panel section-space"><div class="panel-head"><h2>B 层 · 部分满足 / 有缺口 · ${Bt.length} 人</h2>${tag('补充研究','amber')}</div>${Bt.map(llCard).join('')||'<p class="muted">暂无。</p>'}</section>`}`;
}
function llCard(r){const j=db.jobs.find(x=>x.id===r.latestJobId);return `<article class="record ll-card"><div class="record-top"><div class="row"><span class="avatar">${esc(r.person.name.slice(-1))}</span><div><h3>${personBtn(r.personId)} ${tag(r.tier+' 层',r.tier==='A'?'green':'amber')}</h3>${action('persona','查看人才画像',`data-id="${esc(r.personId)}"`,'link','persona')}<span class="muted">最近已知：${esc(project(j.projectId).name)} · ${esc(M.roleAt(j,'all',db))} · ${esc(timeText(j))}</span></div></div>${action('poolNeed',requirementNow()?(requirementNow().poolPersonIds.includes(r.personId)&&db.pool.includes(r.personId)?'已关联此需求':'加入此需求人才池'):(db.pool.includes(r.personId)?'已在人才池':'加入人才池'),`data-id="${r.personId}"`,'btn secondary','pool')}</div><div class="ll-cols"><div><b>命中依据</b>${r.hits.map(h=>`<p>${tag(h.label,'green')} ${projectLink(h.projectId,db.jobs.find(x=>x.id===h.jobId).start,r.personId)} ${action('job','任职 '+h.jobId,`data-id="${h.jobId}" data-year="all"`,'link','evidence')} ${evidenceLink(h.evidenceIds)}</p>`).join('')}</div><div><b>缺口</b>${r.gaps.map(g=>`<p class="muted">· ${esc(g)}</p>`).join('')||'<p class="muted">无硬条件缺口</p>'}<b>下一步核验</b>${r.checks.map(c=>`<p class="muted">· ${esc(c)}</p>`).join('')}</div></div></article>`;}

/* ---------------- 可行动人才池 ---------------- */
function poolBoard(){
 const items=currentPoolForRequirements();
 return `<section class="panel"><div class="panel-head"><h2>人才池 · ${items.length} 人 · 按跟进状态</h2>${info('poolFollow')}</div><p class="muted">跟进状态、负责人、复核日期与备注都是工作记录，不写入人员事实；推荐依据直接引用已发布经历与原文。不记录联系方式，不推断求职意向。</p>${requirementPoolControl()}<div class="kanban">${M.POOL_STATUS.map(s=>{const list=items.filter(i=>i.meta.status===s);return `<div class="kan-col"><h3>${s} <span class="count">${list.length}</span></h3>${list.map(poolCard).join('')||'<p class="muted small">暂无</p>'}</div>`;}).join('')}</div></section>
 <section class="panel section-space"><div class="panel-head"><h3>关注项目 · 本轮仅本地保存</h3>${info('follow')}</div>${db.follows.map(id=>`<div class="task">${projectLink(id)}${action('follow','取消关注',`data-id="${id}"`)}</div>`).join('')||'<p class="muted">尚未关注项目。</p>'}</section>`;
}
function poolCard(i){const b=i.basis,m=i.meta,j=b.latest;return `<article class="pool-card ${i.overdue?'overdue':''}"><div class="row spread">${personBtn(i.personId)}${i.overdue?tag('已过复核日','red'):m.nextReview?tag('复核 '+m.nextReview):''}</div>${m.need?`<p class="small"><b>需求</b> ${esc(m.need)}</p>`:''}<p class="small muted">最近已知：${j?esc(project(j.projectId).name)+' · '+esc(M.roleAt(j,'all',db))+' · '+esc(timeText(j)):'无已发布任职'}${b.closed?' · 去向未收录':''}</p><div class="chips">${[...new Set(b.caps.map(c=>c.domain+' / '+c.scope))].map(t=>tag(t,'green')).join('')}${b.chief.length?tag('主策任职','green'):''}${!b.caps.length&&!b.chief.length?tag('尚无能力职责证据'):''}</div>${m.note?`<p class="small">${esc(m.note)}</p>`:''}<p class="small muted">负责人 ${esc(m.owner)}</p><div class="actions">${action('poolEdit','更新跟进',`data-id="${i.personId}"`,'link','poolFollow')}${action('pool','移出',`data-id="${i.personId}"`,'link','pool')}</div></article>`;}

/* ---------------- modals ---------------- */
window.extraModals={
 analysis(m){const e=db.events.find(x=>x.id===m.id),a=(db.analyses||[]).find(x=>x.eventId===m.id)||{priority:'P1',signal:'',judgement:'',action:'',window:'',reviewBy:M.addDays(db.observationDate,90)};return ['研判 · '+esc(e.title),`<div class="layer fact"><span class="layer-label">事实层（只读）</span><p>${esc(e.fact)}</p><p class="muted">缺口：${esc(e.gap)}</p>${evidenceLink(e.evidenceIds)}</div><form id="analysisForm"><input type="hidden" name="eventId" value="${e.id}"><div class="formgrid section-space"><label class="field">优先级<select name="priority">${M.PRIORITIES.map(p=>`<option ${a.priority===p?'selected':''}>${p}</option>`).join('')}</select></label><label class="field">下次复核日<input type="date" name="reviewBy" value="${esc(a.reviewBy||'')}"></label></div><label class="field section-space">信号（这件事改变了什么）<textarea name="signal" required>${esc(a.signal)}</textarea></label><label class="field">判断（对团队 / 人才研究意味着什么）<textarea name="judgement" required>${esc(a.judgement)}</textarea></label><label class="field">建议行动<textarea name="action" required>${esc(a.action)}</textarea></label><label class="field">窗口期（人工设定）<input name="window" required value="${esc(a.window)}"></label><p class="hint">判断层与事实分开存储，不进入查询；不得写入候选人意向推断。保存会写入版本日志。</p><div id="analysisError" class="error" hidden></div><div class="actions"><button class="btn">保存研判</button></div></form>`];},
 analysisList(){const as=M.analyses(db);return ['研判信号 · 按优先级',as.map(a=>analysisCard(a)).join('')||'<p>暂无研判。</p>'];},
 delta(){const js=M.publishedJobs(db),init=id=>evidence(id)?.ingestionKind==='历史底库初始化',rows=js.filter(j=>j.evidenceIds.some(id=>!init(id)));return ['本轮新增 / 补证任职',`<p class="muted">相对“历史底库初始化”的变化，全部由人审发布产生。</p>${rows.map(j=>`<div class="task"><span>${personBtn(j.personId)} · ${esc(project(j.projectId).name)} · ${esc(M.roleAt(j,'all',db))} ${tag(j.evidenceIds.every(id=>!init(id))?'新增任职':'补充证据',j.evidenceIds.every(id=>!init(id))?'green':'amber')}</span>${action('job','字段依据',`data-id="${j.id}" data-year="all"`,'link','evidence')}</div>`).join('')||'<p class="empty">尚无。录入并审核林序访谈后，这里会出现 2 段新增、1 段补证。</p>'}`];},
 health(m){const h=M.health(db).find(x=>x.key===m.id);const jobsHtml=(h.jobIds||[]).map(id=>db.jobs.find(j=>j.id===id)).map(j=>`<div class="task"><span>${personBtn(j.personId)} · ${esc(project(j.projectId).name)} · ${esc(M.roleAt(j,'all',db))} · ${esc(timeText(j))}</span>${action('job','字段依据',`data-id="${j.id}" data-year="all"`,'link','evidence')}</div>`).join('');const relHtml=(h.relationIds||[]).map(id=>{const r=db.relationships.find(x=>x.id===id);return `<div class="task"><span>${esc(person(r.subjectId).name)}—${esc(person(r.objectId).name)} · ${esc(r.type)}</span>${action('relation','核验',`data-id="${r.id}"`)}</div>`;}).join('');return ['数据健康度 · '+esc(h.label),`<p><b>${h.value}/${h.total}</b>（${h.pct}%）</p><p class="hint">${esc(h.note)}</p>${jobsHtml||relHtml||'<p class="muted">没有需要列出的记录。</p>'}`];},
 flowEdge(m){const [kind,path]=m.id.split('|'),[from,to]=path.split('>'),f=M.flows(db),e=(kind==='confirmed'?f.edges:f.candidateEdges).find(x=>x.from===from&&x.to===to),label=kind==='confirmed'?'明确转岗':'履历先后 · 待核验';return [`${esc(project(from).name)} → ${esc(project(to).name)} · ${label} · ${e?e.count:0} 人`,(e?e.moves:[]).map(x=>{const a=db.jobs.find(j=>j.id===x.fromJob),b=db.jobs.find(j=>j.id===x.toJob),ev=x.eventId&&db.events.find(e=>e.id===x.eventId);return `<div class="record"><div class="row spread">${personBtn(x.personId)}${tag(x.status,kind==='confirmed'?'green':'amber')}</div><p>${esc(project(a.projectId).name)} · ${esc(M.roleAt(a,'all',db))} · ${esc(timeText(a))}<br>→ ${esc(project(b.projectId).name)} · ${esc(M.roleAt(b,'all',db))} · ${esc(timeText(b))}</p><p class="muted">${esc(x.basis)}${x.gap?' 两段经历之间有空档年份。':''}</p>${ev?`${action('event','明确转岗事件',`data-id="${ev.id}"`,'link','compare')} `:''}${claimLinks(x.claimIds)} ${evidenceLink(x.evidenceIds)}</div>`;}).join('')+`<p class="hint">${kind==='confirmed'?'该路径有已发布事件同时关联人员和前后任职，参与确认净流量。':'这里只确认任职先后，不参与净流量；补到明确转岗事件前保持待核验。'} 不推断离职原因、团队整体迁移或求职意向。</p>`];},
 flowConcurrent(m){const x=M.flows(db).concurrent.find(x=>x.id===m.id);if(!x)return ['同期任职已变化','<p>请刷新页面后重试。</p>'];return [`同期跨项目 · ${esc(person(x.personId).name)}`,`<p>${esc(x.start)}–${esc(x.end)} 年同时收录于 ${x.projectIds.map(id=>projectLink(id)).join(' 与 ')}。</p><p class="hint">${esc(x.warning)}</p>${x.jobIds.map(id=>action('job','任职 '+esc(id),`data-id="${esc(id)}" data-year="all"`,'link','evidence')).join(' ')} ${claimLinks(x.claimIds)} ${evidenceLink(x.evidenceIds)}<p class="muted section-space">同期重叠不自动判定借调、兼职或记录冲突，也不参与确认流入 / 流出。</p>`];},
 plink(m){const l=M.linksFor(db).find(x=>x.id===m.id)||db.projectLinks.find(x=>x.id===m.id);return [`${esc(project(l.fromId).name)} → ${esc(project(l.toId).name)} · ${esc(l.type)}`,`${tag(l.processStatus,l.processStatus==='待核验'?'amber':'green')} ${tag('虚构演示')}<h3 class="section-space">原文依据</h3><div class="quote">${esc(l.quote)}</div><p class="hint">${esc(l.gap)}</p>${evidenceLink(l.evidenceIds)}<div class="actions">${action('correction','创建核验任务',`data-id="${l.id}" data-kind="projectLink"`,'link','correction')}</div>`];},
 poolEdit(m){const it=M.poolItems(db).find(x=>x.personId===m.id),mm=it.meta;return ['跟进 · '+esc(it.person.name),`<form id="poolForm"><input type="hidden" name="personId" value="${m.id}"><div class="formgrid"><label class="field">跟进状态<select name="status">${M.POOL_STATUS.map(s=>`<option ${mm.status===s?'selected':''}>${s}</option>`).join('')}</select></label><label class="field">负责人<input name="owner" required value="${esc(mm.owner)}"></label><label class="field">对应需求<input name="need" value="${esc(mm.need)}"></label><label class="field">下次复核日<input type="date" name="nextReview" value="${esc(mm.nextReview)}"></label></div><label class="field section-space">依据 / 备注（标记“可推荐给业务”时必填）<textarea name="note">${esc(mm.note)}</textarea></label><p class="hint">工作记录不修改人员事实；不得写入意向推断或联系方式。</p><div id="poolError" class="error" hidden></div><div class="actions"><button class="btn">保存跟进</button></div></form><h3 class="section-space">跟进记录</h3>${(mm.history||[]).slice().reverse().map(h=>`<p class="small">${esc(h.date)} · ${esc(h.status)} · ${esc(h.note)}</p>`).join('')||'<p class="muted">暂无</p>'}`];}
};

/* ---------------- actions & forms ---------------- */
window.insightActions={
 stat(b){const k=b.dataset.key;if(k==='delta')return openModal('delta');if(k==='p0')return openModal('analysisList');if(k==='poolDue')return go('pool');return false;},
 analysis(b){if(role!=='hr')return toast('研判由 HR 视角维护。');openModal('analysis',b.dataset.id);},
 health(b){openModal('health',b.dataset.key);},
 flowEdge(b){openModal('flowEdge',b.dataset.id);},
 flowConcurrent(b){openModal('flowConcurrent',b.dataset.id);},
 flowProject(b){flowFocusProject=b.dataset.id||'';render();},
 plink(b){openModal('plink',b.dataset.id);},
 heat(b){queryState={project:b.dataset.project,capability:b.dataset.cap};go('search');},
 tlYear(b){projectState.period=b.dataset.year;projectState.tab='org';projectState.highlight='';render();},
 llPreset(b){const p=M.LONGLIST_PRESETS.find(x=>x.id===b.dataset.id);longState={preset:p.id,title:p.title,domains:[...p.domains],minScope:p.minScope,chief:p.chief,genre:p.genre};render();},
 llExport(){const rows=M.longlist(db,longState),q=s=>'"'+String(s).replace(/"/g,'""')+'"';download(`长名单_${longState.title||'需求'}.csv`,'\ufeff'+[['分层','姓名','人员ID','命中依据','缺口','下一步核验'],...rows.map(r=>[r.tier,r.person.name,r.personId,r.hits.map(h=>h.label+'@'+project(h.projectId).name).join('；'),r.gaps.join('；'),r.checks.join('；')])].map(r=>r.map(q).join(',')).join('\n'),'text/csv');toast('已导出；文件只含样本库事实与缺口，不含联系方式。');},
 pool(b){const id=b.dataset.id;if(db.pool.includes(id)){M.poolRemove(db,id);refresh();return toast('已移出人才池；跟进记录一并删除。');}M.poolAdd(db,id,{});refresh();toast('已加入人才池“待研究”，默认30天后复核；没有发送通知。');},
 poolNeed(b){const id=b.dataset.id;if(db.pool.includes(id))return toast('已在人才池，可在人才池中更新需求。');M.poolAdd(db,id,{need:longState.title,reason:'来自需求长名单：'+longState.title});refresh();toast('已加入人才池并记录需求来源。');},
 poolEdit(b){openModal('poolEdit',b.dataset.id);}
};
window.insightForms={
 longlistForm(f,get){longState={preset:'',title:get('title')||'自定义需求',domains:f.getAll('domains').map(String),minScope:+get('minScope')||1,chief:f.has('chief'),genre:get('genre')};render();},
 analysisForm(f,get){if(role!=='hr')return toast('请切换 HR 视角处理。');try{M.saveAnalysis(db,get('eventId'),{priority:get('priority'),signal:get('signal'),judgement:get('judgement'),action:get('action'),window:get('window'),reviewBy:get('reviewBy')});save();modalStack=[];$('#detail').close();render();toast('研判已保存到判断层并写入版本日志；事实未改变。');}catch(err){const el=$('#analysisError');el.hidden=false;el.textContent=err.message;}},
 poolForm(f,get){try{M.poolUpdate(db,get('personId'),{status:get('status'),owner:get('owner'),need:get('need'),nextReview:get('nextReview'),note:get('note')});save();modalStack=[];$('#detail').close();render();toast('跟进已更新；人员事实未改变。');}catch(err){const el=$('#poolError');el.hidden=false;el.textContent=err.message;}}
};
